//! The heartbeat and the presented credential are selected by one SQL statement.
//! Home answers currently use the primary. An unavailable/stale snapshot is never an
//! authentication success; a future replica reader must use this same statement.
use super::{freshness, Proof};
use crate::DbPool;
use anyhow::{ensure, Result};
use chrono::{DateTime, Utc};
use std::time::Instant;

/// Publish on the primary before answering. The timestamp is generated by the database,
/// committed before the snapshot read, and is not replaced by an RPC receipt time. The
/// snapshot is at least as new as this publication, so its age here is checked on this
/// node's clocks; a node whose clock differs from the database's still answers.
pub async fn primary(pool: &DbPool, proof: &Proof) -> Result<Option<DateTime<Utc>>> {
    let policy = freshness::policy()?;
    let read = policy
        .start(Utc::now(), Instant::now())
        .ok_or_else(|| anyhow::anyhow!("Identity freshness is unavailable"))?;
    match pool {
        DbPool::Postgres(pool) => {
            sqlx::query("INSERT INTO identity_heartbeat(id,committed_at) VALUES(1,clock_timestamp()) ON CONFLICT(id) DO UPDATE SET committed_at=excluded.committed_at")
                .execute(pool).await?;
        }
        DbPool::Sqlite(pool) => {
            sqlx::query("INSERT INTO identity_heartbeat(id,committed_at) VALUES(1,strftime('%Y-%m-%dT%H:%M:%f000Z','now')) ON CONFLICT(id) DO UPDATE SET committed_at=excluded.committed_at")
                .execute(pool).await?;
        }
    }
    ensure!(
        read.current(Utc::now(), Instant::now()),
        "Identity heartbeat publication expired"
    );
    let heartbeat = snapshot(pool, proof).await?;
    if heartbeat.is_some() {
        ensure!(
            read.prove_published(None, Utc::now(), Instant::now())
                .is_some(),
            "Identity snapshot is stale"
        );
    }
    Ok(heartbeat)
}

/// No separate heartbeat read is allowed: credential absence and heartbeat freshness
/// must describe the same snapshot. Account restrictions participate in that snapshot.
pub async fn snapshot(pool: &DbPool, proof: &Proof) -> Result<Option<DateTime<Utc>>> {
    proof.validate()?;
    let (table, key, value, expires) = match proof {
        // A token stays with its account when the account moves, so a native token row
        // here may carry another cell's prefix; stub accounts hold no native tokens.
        Proof::Token { hash, .. } => ("personal_access_tokens", "token_hash", hash, true),
        Proof::Session { home, value } => {
            if !pool.owns_prefix(*home) {
                return Ok(None);
            }
            ("sessions", "id", value, true)
        }
        Proof::Ssh { fingerprint } => ("ssh_keys", "fingerprint", fingerprint, false),
    };
    let query = |clock: &str| {
        let expiry = if expires {
            format!(" AND (c.expires_at IS NULL OR c.expires_at>{clock})")
        } else {
            String::new()
        };
        format!("SELECT h.committed_at FROM identity_heartbeat h WHERE h.id=1 AND EXISTS(SELECT 1 FROM {table} c JOIN users u ON u.id=c.user_id WHERE c.{key}=$1 AND NOT u.is_stub AND NOT u.is_banned AND NOT u.must_change_password{expiry})")
    };
    Ok(match pool {
        DbPool::Postgres(pool) => {
            sqlx::query_scalar(&query("clock_timestamp()"))
                .bind(value)
                .fetch_optional(pool)
                .await?
        }
        DbPool::Sqlite(pool) => {
            sqlx::query_scalar(&query("strftime('%Y-%m-%dT%H:%M:%f000Z','now')"))
                .bind(value)
                .fetch_optional(pool)
                .await?
        }
    })
}
